CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, unit TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'member', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS invites (email TEXT PRIMARY KEY, display_name TEXT NOT NULL, unit TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'member', added_by TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS models (id TEXT PRIMARY KEY, code TEXT NOT NULL, color TEXT NOT NULL, season TEXT NOT NULL DEFAULT '', factory TEXT NOT NULL DEFAULT '', phase TEXT NOT NULL DEFAULT 'preparation', launch_date TEXT NOT NULL DEFAULT '', readiness_date TEXT NOT NULL DEFAULT '', creator_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(code,color));
CREATE TABLE IF NOT EXISTS posts (id TEXT PRIMARY KEY, model_id TEXT NOT NULL REFERENCES models(id), kind TEXT NOT NULL DEFAULT 'issue', title TEXT NOT NULL, body TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'open', owner_unit TEXT NOT NULL DEFAULT '', due_at TEXT, source TEXT NOT NULL DEFAULT 'manual', source_hash TEXT, author_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, closed_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS posts_source_hash ON posts(source_hash) WHERE source_hash IS NOT NULL;
CREATE INDEX IF NOT EXISTS posts_model_created ON posts(model_id, created_at DESC);
CREATE TABLE IF NOT EXISTS assignments (id TEXT PRIMARY KEY, post_id TEXT NOT NULL REFERENCES posts(id), assignee_id TEXT REFERENCES users(id), assignee_email TEXT, unit TEXT NOT NULL DEFAULT '', request TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending', due_at TEXT, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES users(id));
CREATE INDEX IF NOT EXISTS assignments_user ON assignments(assignee_id,status);
CREATE TABLE IF NOT EXISTS comments (id TEXT PRIMARY KEY, post_id TEXT NOT NULL REFERENCES posts(id), author_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), post_id TEXT NOT NULL REFERENCES posts(id), actor_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL, message TEXT NOT NULL, created_at TEXT NOT NULL, read_at TEXT);
CREATE INDEX IF NOT EXISTS notifications_user ON notifications(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, details TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attachments (id TEXT PRIMARY KEY, post_id TEXT REFERENCES posts(id), comment_id TEXT REFERENCES comments(id), uploader_id TEXT NOT NULL REFERENCES users(id), object_key TEXT NOT NULL, name TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS checklist_items (id TEXT PRIMARY KEY, model_id TEXT NOT NULL REFERENCES models(id), template_id TEXT NOT NULL, unit TEXT NOT NULL, title_zh TEXT NOT NULL, title_vi TEXT NOT NULL, title_en TEXT NOT NULL, target_rule TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending', note TEXT NOT NULL DEFAULT '', updated_at TEXT, updated_by TEXT REFERENCES users(id));
CREATE INDEX IF NOT EXISTS checklist_model_unit ON checklist_items(model_id,unit);
